--[[
    ================================================================================
    DEOBFUSCATED & CLEANED SCRIPT - CHILLI HUB (STEAL AN EGG - v2100)
    ================================================================================
    - Game tương thích: Steal An Egg (Roblox)
    - Cấu trúc đã được giải mã & tách thành 3 phân hệ rõ ràng:
        1. LOADING_SCREEN_MODULE : Giao diện màn hình chờ (Loading Screen 0% -> 100%)
        2. UI_LIBRARY_MODULE     : Thư viện giao diện người dùng (Window, Tabs, QuickBars, Configs, Search)
        3. MAIN_GAME_SCRIPT      : Toàn bộ 47 module chức năng chính của game:
           + Auto Steal (Instant Steal V1/V2/V3, Tween, Teleport, Anti-Guard, Carry/Drop)
           + Egg Predictor & Chilli Finder HUD (Dự đoán trứng hiếm, ESP, Live Feed)
           + Auto Server Hop & Egg Finder (Tự động đổi server săn trứng hiếm)
           + Butterfly Bloom, Shooting Star, Wisp Quest, Banjo Cricket
           + Auto Mutate, Auto Place Egg, Auto Hatch & Equip, Auto Treadmill
           + Auto Sell (Pet & Egg), Auto Fuse Machine, Auto Favorite
           + Admin Abuse (Capture The Egg, Admin Treadmill, Minigame Eggs: Red Light Green Light / T-Rex)
           + Player (Speed Boost, Infinite Jump, Invisibility, Anti-Ragdoll, Anti-Trap, Auto Hit / Combat)
           + Discord Webhook, Optimizer, Anti-AFK, Multi-language & Config System
    - Đã gỡ bỏ hoàn toàn cơ chế Anti-Rebrand (fakeV / fakeG / reclaim) để đổi tên Menu
      thoải mái mà không bị lỗi chữ hay khóa tính năng.
    ================================================================================
]]

