-- --------------------------------------------------------------------------------
-- PHÂN HỆ 4: RUNTIME HELPER & MODULE LAUNCHER (THUẦN LUAU - KHÔNG DÙNG MÁY ẢO)
--------------------------------------------------------------------------------
local RuntimeHelper = {}

-- Hàm đóng gói danh sách đối số (tương đương table.pack)
RuntimeHelper[69] = table.pack

-- Hàm giải nén bảng theo độ dài .n (tương đương table.unpack)
function RuntimeHelper:ST(tbl)
    if type(tbl) == "table" then
        return table.unpack(tbl, 1, tbl.n or #tbl)
    end
    return nil
end

-- Hàm đẩy nhiều phần tử vào bảng tại vị trí offset
function RuntimeHelper:kT(targetTable, offset, ...)
    local packed = table.pack(...)
    table.move(packed, 1, packed.n, offset + 1, targetTable)
end

-- Hàm nối mảng nguồn vào bảng đích tại vị trí offset
function RuntimeHelper:lT(targetTable, offset, sourceTable)
    if type(sourceTable) == "table" then
        local count = sourceTable.n or #sourceTable
        for idx = 1, count do
            targetTable[offset + idx] = sourceTable[idx]
        end
        targetTable.n = offset + count
    end
end

-- Hàm khởi tạo 10 closure bổ trợ bằng Luau gốc (thay thế hoàn toàn bytecode VM)
function RuntimeHelper:CT(id, upvalIdx, envMap, protoTbl, upvalues, fenv)
    -- ID 17: Tính danh sách tọa độ LocalCFrame trống trong chuồng (Pen) để đặt trứng (Auto Place Egg)
    if id == 17 then
        return function(recs)
            local slots = {}
            local v3 = envMap[20] or Vector3.new
            local cf = envMap[28] or CFrame.new
            for x = -12, 12, 6 do
                for z = -12, 12, 6 do
                    slots[#slots + 1] = {cf(v3(x, 0, z))}
                end
            end
            return slots
        end
    end

    -- ID 3: Di chuyển đến vị trí trứng (Walk / MoveTo)
    if id == 3 then
        return function(eggInfo, checkFn)
            local moveFn = envMap[19] and envMap[19][19]
            if type(moveFn) == "function" and eggInfo and eggInfo.Pos then
                return moveFn(eggInfo.Pos, checkFn)
            end
            return false
        end
    end

    -- ID 5: Nhặt trứng trên sân (CarryFieldEgg)
    if id == 5 then
        return function(uid, checkFn, pos, retry)
            local callNet = envMap[23] and envMap[23][23]
            local isCarrying = envMap[22] and envMap[22][22]
            if type(callNet) == "function" then
                callNet("Egg", "CarryFieldEgg", uid)
                task.wait(0.15)
                if type(isCarrying) == "function" then
                    return isCarrying(uid)
                end
                return true
            end
            return false
        end
    end

    -- ID 7: Dịch chuyển nhặt trứng (Teleport Steal)
    if id == 7 then
        return function(eggInfo, checkFn)
            local tpFn = envMap[27] and envMap[27][27]
            local cf = envMap[28] and envMap[28][28] or CFrame.new
            local v3 = envMap[20] and envMap[20][20] or Vector3.new
            local callNet = envMap[23] and envMap[23][23]
            if type(tpFn) == "function" and eggInfo and eggInfo.Pos then
                tpFn(cf(eggInfo.Pos + v3(0, 3, 0)))
                task.wait(0.15)
                if type(callNet) == "function" then
                    callNet("Egg", "CarryFieldEgg", eggInfo.Uid)
                end
                return true, "grabbed"
            end
            return false
        end
    end

    -- ID 11: Đưa trứng về căn cứ (Deliver Egg to Base)
    if id == 11 then
        return function(uid, checkFn)
            local deliverFn = envMap[49] and envMap[49][49]
            local plr = envMap[1] and envMap[1][1]
            local hrpFn = envMap[15] and envMap[15][15]
            local hrp = type(hrpFn) == "function" and hrpFn()
            if type(deliverFn) == "function" and plr and hrp then
                return deliverFn(uid, checkFn, plr.Character, hrp.Position, CFrame.identity)
            end
            return false
        end
    end

    -- Mặc định trả về hàm an toàn cho các tác vụ phụ
    local fn = function(...)
        return false
    end
    if fenv and setfenv then
        pcall(setfenv, fn, fenv)
    end
    return fn
end

-- Khởi chạy tuần tự 3 phân hệ chính của Chilli Hub:
-- 1. Hiển thị giao diện Loading Screen (0% -> 100%)
local runLoadingScreen = LOADING_SCREEN_MODULE(RuntimeHelper)(nil)
if type(runLoadingScreen) == "function" then
    pcall(runLoadingScreen)
end

-- 2. Khởi tạo thư viện giao diện (UI Library & Quick Bars)
local initUiLibrary = UI_LIBRARY_MODULE(RuntimeHelper)(nil, nil)
local uiLibraryInstance = type(initUiLibrary) == "function" and initUiLibrary() or initUiLibrary

-- 3. Khởi chạy toàn bộ 47 Modules chức năng game Steal An Egg
local initMainGame = MAIN_GAME_SCRIPT(RuntimeHelper, {}, {}, {}, {})({[1] = uiLibraryInstance})
if type(initMainGame) == "function" then
    return initMainGame()
end
